<script lang="ts">import {enhance} from '$app/forms'; let {data,form}=$props(); let busy=$state<string|null>(null); const weekday=new Intl.DateTimeFormat('en-PH',{weekday:'short'}); const dayName=(day:number)=>weekday.format(new Date(2026,7,9+day)); const time=(value:string)=>{const [hour,minute]=value.split(':').map(Number);return new Intl.DateTimeFormat('en-PH',{hour:'numeric',minute:'2-digit'}).format(new Date(2026,0,1,hour,minute));}; const needsReview=$derived(data.items.filter((i:any)=>i.reviewStatus!=='verified').length); const verified=$derived(data.items.filter((i:any)=>i.reviewStatus==='verified'&&i.publicationStatus!=='published').length); const published=$derived(data.items.filter((i:any)=>i.publicationStatus==='published').length);</script>
<svelte:head><title>Schedule Review · IMS Academic Hub</title></svelte:head>
<header class="border-b border-line pb-4"><p class="font-mono text-xs uppercase tracking-[.14em] text-ims-blue-ink">Publication gate</p><h2 class="mt-1 text-4xl font-semibold tracking-[-.05em]">Schedule review</h2><p class="mt-1 max-w-prose leading-relaxed text-muted">Imported schedules stay private until verified and explicitly published.</p></header>{#if form?.reviewError}<div class="mt-4 border-l-4 border-danger bg-red-50 p-3 text-red-900" role="alert">{form.reviewError}</div>{:else if form?.reviewSuccess}<div class="mt-4 border-l-4 border-ims-green bg-green-50 p-3 text-green-900" role="status">{form.reviewSuccess}</div>{/if}
<div class="mt-4 grid grid-cols-3 border-y border-line bg-white">{#each [['Needs verification',needsReview,'not public'],['Verified',verified,'waiting'],['Published',published,'student-facing']] as metric}<article class="grid gap-1 border-r border-line p-3"><span class="text-sm text-muted">{metric[0]}</span><strong class="font-mono text-3xl">{metric[1]}</strong><small class="text-muted">{metric[2]}</small></article>{/each}</div>
{#if data.items.length===0}<section class="mt-4 grid justify-items-start gap-3 border-l-4 border-ims-green bg-white p-5"><h3 class="text-xl font-semibold">No current-term schedules to review.</h3><p class="max-w-prose text-muted">Apply a validated import first. The queue populates without exposing rows to students.</p><a class="inline-flex min-h-11 items-center border border-line-strong px-3 font-bold no-underline" href="/admin/imports">Open Imports</a></section>{:else}<div class="mt-4 grid gap-4">{#each data.items as item (item.id)}<article class="grid gap-4 border border-line-strong bg-white p-4"><header class="flex flex-col gap-3 border-b border-line pb-3 sm:flex-row sm:items-start sm:justify-between"><div><p class="font-mono text-xs uppercase tracking-[.12em] text-ims-blue-ink">{item.courseCode} · Section {item.sectionCode}</p><h3 class="text-xl font-semibold">{item.courseTitle??'Current-term schedule'}</h3></div><div class="flex flex-wrap gap-2">{#each [['Review',item.reviewStatus,item.reviewStatus==='verified'],['Visibility',item.publicationStatus,item.publicationStatus==='published']] as status}<span class={`border px-2 py-1 text-xs font-bold capitalize ${status[2]?'border-green-200 bg-green-50 text-green-800':'border-line bg-slate-50 text-muted'}`}>{status[0]} · {String(status[1]).replace('_',' ')}</span>{/each}</div></header>
<div class="grid gap-4 lg:grid-cols-[1.3fr_.7fr]"><section><span class="font-mono text-xs uppercase text-muted">Meetings</span>{#if item.meetings.length}<div class="mt-2 divide-y divide-line border-y border-line">{#each item.meetings as meeting}<div class="grid min-h-12 grid-cols-[3.5rem_1fr_auto] items-center gap-2 px-3 py-2"><strong>{dayName(meeting.weekday)}</strong><span class="font-mono">{time(meeting.startsAt)}–{time(meeting.endsAt)}</span>{#if meeting.roomId}<a class="font-bold text-ims-blue-ink" href={`/room/${meeting.roomId}`}>{meeting.roomName??meeting.roomId.toUpperCase()}</a>{:else}<span class="text-muted">TBA</span>{/if}</div>{/each}</div>{:else}<p class="mt-2 text-sm text-muted">No meeting rows attached.</p>{/if}</section><section><span class="font-mono text-xs uppercase text-muted">Faculty</span>{#if item.faculty.length}<div class="mt-2 flex flex-wrap gap-2">{#each item.faculty as person}<span class="border border-sky-200 bg-sky-50 px-2 py-1 text-sm font-bold text-ims-blue-ink">{person.displayName}</span>{/each}</div>{:else}<p class="mt-2 text-sm text-muted">No resolved faculty assignment.</p>{/if}</section></div>
{#if item.lastEvent}<p class="border-t border-line pt-3 text-sm text-muted">Last review action: <strong>{item.lastEvent.action}</strong>{item.lastEvent.note?` · ${item.lastEvent.note}`:''}</p>{/if}
<form method="POST" class="grid gap-3 border-t border-line pt-3" use:enhance={()=>{busy=item.id;return async({update})=>{await update();busy=null;};}}><input type="hidden" name="sectionId" value={item.id}/><label class="grid gap-1.5 text-sm font-bold"><span>Review note <small class="font-normal text-muted">optional</small></span><input class="min-h-11 border border-line-strong px-3" name="note" type="text" maxlength="500" placeholder="Add context for the audit trail…"/></label><div class="flex flex-wrap items-center gap-2">{#if item.reviewStatus!=='verified'}<button class="min-h-11 border border-line-strong px-3 font-bold" formaction="?/verify" disabled={busy===item.id}>Verify Schedule</button>{:else}<button class="min-h-11 px-3 font-bold text-muted" formaction="?/returnForReview" disabled={busy===item.id}>Return for Review</button>{/if}{#if data.canPublish}{#if item.publicationStatus==='published'}<button class="min-h-11 px-3 font-bold text-danger" formaction="?/withdraw" disabled={busy===item.id}>Withdraw</button>{:else}<button class="min-h-11 bg-ims-blue-deep px-3 font-bold text-white disabled:opacity-40" formaction="?/publish" disabled={busy===item.id||item.reviewStatus!=='verified'}>Publish</button>{/if}{:else}<span class="text-sm text-muted">Only administrators can publish.</span>{/if}</div></form></article>{/each}</div>{/if}
